<?php
require_once __DIR__ . '/../database/database.php'; require_once __DIR__ . '/../app/auth.php'; require_once __DIR__ . '/../app/layout.php'; requireLogin();
$sessionId=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT); if(!$sessionId){header('Location: sessions.php');exit;}
$stmt=$pdo->prepare('SELECT s.*,p.id AS project_id,p.name AS project_name,p.description AS project_description FROM sessions s JOIN projects p ON p.id=s.project_id WHERE s.id=? AND p.user_id=? LIMIT 1');$stmt->execute([$sessionId,$_SESSION['user_id']]);$session=$stmt->fetch();if(!$session){header('Location: sessions.php');exit;}
$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){ $objective=trim($_POST['objective']??'');$accomplishments=trim($_POST['accomplishments']??'');$remaining=trim($_POST['remaining_work']??'');$next=trim($_POST['next_step']??'');$finish=isset($_POST['finish']);$stmt=$pdo->prepare('UPDATE sessions SET objective=?, accomplishments=?, remaining_work=?, next_step=?, ended_at=CASE WHEN ? THEN NOW() ELSE ended_at END WHERE id=?');$stmt->execute([$objective?:null,$accomplishments?:null,$remaining?:null,$next?:null,$finish,$sessionId]);header('Location: session.php?id='.$sessionId.($finish?'&saved=1':'&saved=1'));exit;}
$duration=$session['ended_at']?strtotime($session['ended_at'])-strtotime($session['started_at']):time()-strtotime($session['started_at']);$hours=floor($duration/3600);$mins=floor(($duration%3600)/60);$durationLabel=$hours?($hours.'h '.$mins.'m'):($mins.'m');
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Session | Project Continuum</title><link rel="stylesheet" href="../assets/css/app.css"></head><body><div class="app-shell"><?php renderSidebar('sessions');?><main class="main-content"><a class="back-link" href="project.php?id=<?= (int)$session['project_id'] ?>">← Back to <?=htmlspecialchars($session['project_name'])?></a><header class="project-heading"><div><p class="eyebrow"><?= $session['ended_at']?'Session summary':'Active work session' ?></p><h1><?=htmlspecialchars($session['project_name'])?></h1><p class="metadata">Started <?=date('M j, Y · g:i A',strtotime($session['started_at']))?> · <?=htmlspecialchars($durationLabel)?></p></div><?php if(!$session['ended_at']):?><span class="badge in-progress">In progress</span><?php else:?><span class="badge completed">Completed</span><?php endif;?></header>
<?php if(isset($_GET['saved'])):?><div class="card panel" style="padding:12px 18px;margin-bottom:16px;color:#147351">Your continuity context was saved.</div><?php endif;?><div class="content-grid"><section class="card panel"><h2 class="panel-title">What happened in this session?</h2><p class="metadata">Capture enough context that future you can resume without guessing.</p><form method="post"><div class="field"><label for="objective">What did you intend to do?</label><textarea id="objective" name="objective" rows="3" placeholder="Today's focus..."><?=htmlspecialchars($session['objective']??'')?></textarea></div><div class="field"><label for="accomplishments">What did you accomplish?</label><textarea id="accomplishments" name="accomplishments" rows="4" placeholder="Completed work, decisions, discoveries..."><?=htmlspecialchars($session['accomplishments']??'')?></textarea></div><div class="field"><label for="remaining_work">What remains unfinished?</label><textarea id="remaining_work" name="remaining_work" rows="3" placeholder="Work still to do, blockers, open questions..."><?=htmlspecialchars($session['remaining_work']??'')?></textarea></div><div class="field"><label for="next_step">The exact next step</label><input id="next_step" name="next_step" value="<?=htmlspecialchars($session['next_step']??'')?>" placeholder="When I return, I will..."></div><button class="button" type="submit" name="save">Save context</button><?php if(!$session['ended_at']):?><button class="button secondary" type="submit" name="finish" style="margin-left:8px">Finish session</button><?php endif;?></form></section><aside class="card panel"><h2 class="panel-title">Resume cue</h2><p class="metadata">Your next return point is always visible from the dashboard.</p><div class="note"><strong>Next step</strong><br><?=htmlspecialchars($session['next_step']?:'Write a concrete next step before finishing.')?></div><a class="button secondary" href="project.php?id=<?= (int)$session['project_id'] ?>">View project</a></aside></div></main></div></body></html>
